// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public {
        c = new MyContract();
        vm.deal(address(c), 100 ether);
    }
    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(amount > 0 && amount <= 100 ether);
        vm.assume(receiver != address(c) && receiver != address(0x000000000000000000000000000000000000dEaD));
        uint256 balBefore = receiver.balance;
        vm.prank(address(this));
        c.sendTo(receiver, amount);
        assertTrue(receiver.balance == balBefore + amount);
    }
}
